  'pushd.installIos': "iPhone або iPad: відкрийте LANKA в Safari, натисніть «Поділитися» → «На початковий екран», потім запустіть LANKA з іконки й увійдіть. Потрібна iOS або iPadOS 16.4 чи новіша. Якщо LANKA вже на початковому екрані — відкрийте її звідти.",
