  'pushd.installChromium': "Комп’ютер: у Chrome чи Edge натисніть значок встановлення в адресному рядку (або меню → «Установити LANKA»), потім відкрийте LANKA як застосунок.",
  'pushd.installSafari': "Mac: у Safari виберіть «Файл» → «Додати в Dock», потім відкрийте LANKA з Dock.",
