  'pushd.denied': "Сповіщення для LANKA заборонено на цьому пристрої. Повторно дозвіл не запитуємо.",
  'pushd.deniedIos': "Відкрийте «Параметри» → «Сповіщення» → LANKA й дозвольте сповіщення, потім поверніться в LANKA.",
