  'pushd.deniedDesktop': "Дозвольте сповіщення для LANKA в налаштуваннях сайту (значок біля адреси) або в системних налаштуваннях сповіщень, потім поверніться в LANKA.",
  'pushd.grantedNoServer': "Дозвіл на сповіщення є, але цей пристрій не підключено до вашого облікового запису. Увімкніть перемикач.",
