  'sig.UNFINISHED_NO_NEXT.how': "Як у звіті «Незавершене лікування»: у плані є невиконані позиції, частину робіт уже виконано (за останні 180 днів), у пацієнта є завершений візит, немає майбутнього запису й активного нагадування. Рахуємо тих, у кого після останньої виконаної роботи минуло щонайменше вказану кількість днів. Сам план без розпочатого лікування не враховується.",
