  'pushd.installAndroid': "Android: в Chrome откройте меню ⋮ → «Установить приложение» (или «Добавить на главный экран»), затем запустите LANKA с иконки. Если LANKA уже установлена — откройте её с иконки.",
  'pushd.installChromium': "Компьютер: в Chrome или Edge нажмите значок установки в адресной строке (или меню → «Установить LANKA»), затем откройте LANKA как приложение.",
