  'pr.definitions': "Новые пациенты — карточки, созданные в Cliniccards за период. Доля отмен и неявок: (отменено + не пришёл) ÷ визиты с известным результатом (состоялся, в клинике, в кресле, не пришёл, отменено, перенесено) — так же, как в сигнале «Отмены и неявки». Визиты без отметки, пришёл ли пациент (запланировано, подтверждено, не подтверждено, бронь), в долю не входят и показаны отдельно. Отчёт «Визиты без итога» считает иначе: туда попадают и «в клинике» и «в кресле», а бронь — нет. Оплаты — по дате оплаты, каждая валюта отдельно.",
