  'sig.PAYMENTS_DROP.how': "Сумма оплат из Cliniccards за последние полные дни (по киевскому времени) сравнивается с таким же предыдущим периодом — так же, как в отчёте «Выставлено и оплачено». Сравниваем только оплаты в одной валюте. Если в предыдущем периоде меньше 10 оплат, процент не считаем; ноль оплат сейчас — настоящий спад.",
  'sig.UNFINISHED_NO_NEXT.what': "Пациентов без записи {d} дн. и дольше: **{n}** (всего без записи: {total}).",
  'sig.UNFINISHED_NO_NEXT.open': "Незавершённое лечение",
  'sig.UNFINISHED_NO_NEXT.why': "Начатое лечение без следующего визита часто остаётся незавершённым, если пациенту не напомнить.",
  'sig.UNFINISHED_NO_NEXT.how': "Как в отчёте «Незавершённое лечение»: в плане есть невыполненные позиции, часть работ уже выполнена (за последние 180 дней), у пациента есть завершённый визит, нет будущей записи и активного напоминания. Считаем тех, у кого после последней выполненной работы прошло не меньше указанного числа дней. Сам план без начатого лечения не учитывается.",
  'sig.NO_REBOOK.what': "Пациентов без новой записи после отмены или неявки: **{n}** из {total}.",
  'sig.NO_REBOOK.open': "Неявки и отмены",
  'sig.NO_REBOOK.why': "Пациент, который отменил или не пришёл и не записался снова, может не вернуться без напоминания.",
  'sig.NO_REBOOK.how': "Визиты со статусом «отменён» или «не пришёл» за последние 30 дней, после которых прошло не меньше указанного числа дней. Пациент не учитывается, если после этого у него был завершённый визит или есть будущая запись. Каждый пациент — один раз.",
