  'sig.OVERDUE_TASKS.how': "Открытые задачи LANKA, у которых прошёл день выполнения. Выполненные и отменённые не считаются. Это данные LANKA, синхронизация не нужна; в уведомлении только количество.",
  'sig.SYNC_OVERDUE.what': "Данные не обновлялись **{h} ч** (последнее обновление: {date}).",
