  'wl.rules': "Предложение идёт в Telegram через очередь подтверждения (или само, если у вас включены автоматические служебные сообщения). У пациента есть несколько часов, чтобы ответить: если согласился, время удерживается за ним и появляется заявка администратору; если отказался или молчит, время достаётся следующему. Предлагать можно только тем, кто подключил Telegram.",
